import 'package:flutter_test/flutter_test.dart';
import 'package:upc/domain/calculator.dart';
Stay stay(String city,{int rooms=10,int price=45000})=>Stay(city,checkIn:'2026-10-10',checkOut:'2026-10-14',group:RoomLine('group',quantity:rooms,manualPrice:price),individual:[RoomLine('dbl',type:RoomType.dbl,quantity:2,manualPrice:50000),RoomLine('trpl',type:RoomType.trpl,quantity:3,manualPrice:65000),RoomLine('quad',type:RoomType.quad,quantity:1,manualPrice:80000)]);
Draft draft()=>Draft('123',name:'Test',madinah:stay('madinah'),makkah:stay('makkah')..enabled=false,fx:3.75);
void main(){
 test('GROUP complete room-rate plan: price × rooms × checkout-excluded nights',(){final d=draft();expect(d.madinah.nights.length,4);expect(Calculator.calculate(d,[]).total,1800000);});
 test('INDIVIDUAL actual guests are automatic: 2×2 + 3×3 + 1×4',(){final d=draft()..mode=CalcMode.individual;expect(d.madinah.actualGuests,17);expect(Calculator.calculate(d,[]).total,(2*50000+3*65000+80000)*4);d.madinah.individual.first.plan=RatePlan.fb;expect(d.madinah.actualGuests,17);});
 test('City GROUP guest counts are independent and do not multiply room prices',(){final d=draft();d.madinah.totalPax=50;d.makkah.totalPax=30;expect(d.madinah.totalPax,50);expect(d.makkah.totalPax,30);expect(Calculator.calculate(d,[]).total,1800000);});
 test('Inclusive period dates; automatic nightly splitting',(){final d=draft();d.madinah.hotelId='hotel';d.madinah.group.manualPrice=null;final h=Hotel('hotel','Test','madinah',[Period('a','2026-10-10','2026-10-11',{'GROUP/roomOnly':45000}),Period('b','2026-10-12','2026-10-13',{'GROUP/roomOnly':50000})]);final r=Calculator.calculate(d,[h]);expect(r.total,1900000);expect(r.madinah.nights.map((n)=>n['price']).toList(),[45000,45000,50000,50000]);});
 test('Overlapping hotel periods rejected, including shared endpoint',(){final h=Hotel('h','Test','madinah');h.addPeriod(Period('a','2026-10-01','2026-10-10',{}));expect(()=>h.addPeriod(Period('b','2026-10-10','2026-10-20',{})),throwsStateError);h.addPeriod(Period('b','2026-10-11','2026-10-20',{}));expect(h.periods.length,2);});
 test('Missing rates never inherit old price; exact night is identified',(){final d=draft();d.madinah.hotelId='hotel';d.madinah.group.manualPrice=null;final h=Hotel('hotel','Test','madinah',[Period('a','2026-10-10','2026-10-12',{'GROUP/roomOnly':45000})]);expect(()=>Calculator.calculate(d,[h]),throwsA(isA<MissingPrice>().having((e)=>e.dates.join(),'dates',contains('2026-10-13'))));});
 test('Different lines of same type and nightly plans',(){final d=draft()..mode=CalcMode.individual;d.madinah.individual=[RoomLine('a',quantity:2,plan:RatePlan.bb,manualPrice:30000),RoomLine('b',quantity:1,plan:RatePlan.hb,manualPrice:50000)];d.madinah.individual.first.overrides['2026-10-11']=NightOverride(RatePlan.fb,70000);expect(Calculator.calculate(d,[]).total,520000);expect(d.madinah.actualGuests,6);});
 test('Calculator manual override does not mutate hotel database',(){final d=draft();d.madinah.group.manualPrice=null;d.madinah.hotelId='h';final h=Hotel('h','Test','madinah',[Period('a','2026-10-10','2026-10-13',{'GROUP/roomOnly':45000})]);d.madinah.group.overrides['2026-10-10']=NightOverride(RatePlan.fb,80000);expect(Calculator.calculate(d,[h]).total,2150000);expect(h.price('2026-10-10','GROUP/roomOnly'),45000);});
 test('Fixed, per person and quantity with independent Add/Deduct signs',(){final d=draft();d.services=[ExtraService('bus',unitPrice:280000),ExtraService('visa',type:ServiceType.perPerson,quantity:50,unitPrice:12000),ExtraService('mut',type:ServiceType.quantity,quantity:3,unitPrice:70000),ExtraService('zam',type:ServiceType.quantity,quantity:10,unitPrice:5000),ExtraService('disc',unitPrice:30000,deduct:true),ExtraService('refund',type:ServiceType.perPerson,quantity:5,unitPrice:4000,deduct:true)];expect(Calculator.calculate(d,[]).services,1090000);});
 test('USD direction SAR divided by SAR per USD; no cached rate = unavailable',(){final d=draft();final r=Calculator.calculate(d,[]);expect(r.usd,'4800.00');d.fx=null;expect(Calculator.calculate(d,[]).usd,isNull);d.fx=0;expect(()=>Calculator.calculate(d,[]),throwsArgumentError);});
 test('Duplicate freezes original nightly values, never reprices',(){final d=draft();final snap=Calculator.snapshot(d,[]);final dup=Calculator.duplicate(snap,'new');dup.madinah.group.manualPrice=null;expect(dup.id,'new');expect(Calculator.calculate(dup,[]).total,1800000);dup.madinah.group.quantity=1;expect(Calculator.calculate(dup,[]).total,180000);expect((snap['result'] as Map)['total'],1800000);});
 test('Draft roundtrip retains FX override, nightly override, services and room lines',(){final d=draft()..fxManual=true;d.services.add(ExtraService('s',type:ServiceType.quantity,quantity:4,unitPrice:123));d.madinah.group.overrides['2026-10-10']=NightOverride(RatePlan.bb,12345);expect(d.copy().toJson(),d.toJson());});
 test('Negative room input and invalid dates rejected',(){final d=draft();d.madinah.checkOut=d.madinah.checkIn;expect(()=>Calculator.calculate(d,[]),throwsArgumentError);d.madinah.checkOut='2026-10-14';d.madinah.group.quantity=-1;expect(()=>Calculator.calculate(d,[]),throwsArgumentError);});
 test('Amounts retain exact integer minor units',(){expect(cents('123.45'),12345);expect(cents('0.01'),1);expect(cents('1,234.50'),123450);expect(money(-12345),'-123.45');expect(()=>cents('-1'),throwsFormatException);expect(()=>cents('2.999'),throwsFormatException);});
}
